#!/usr/bin/env bash
# test-agents-skills.sh — the portable .agents/skills/ mirror.
#
# WHAT THIS PINS
#   .agents/skills/<name> is a relative symlink to skills/<domain>/<name>,
#   generated by scripts/build-agents-skills.sh and read one level deep by Codex,
#   Gemini CLI (as the .gemini/skills alias), Antigravity and Copilot. The ways
#   it can be silently wrong are the same as .gemini/skills/: empty, missing a
#   skill, carrying a stale or dangling entry, or an absolute link that breaks
#   the moment the clone moves. Each is planted in a scratch copy and must fail
#   --check; the real tree must pass and agree with .gemini/skills/.
#
# Needs nothing beyond coreutils and git. Exit 0 if all pass, 1 otherwise.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=tests/lib/harness.sh
source "$ROOT/tests/lib/harness.sh"

GEN="$ROOT/scripts/build-agents-skills.sh"
MIRROR="$ROOT/.agents/skills"
[ -f "$GEN" ] || { echo "FATAL: generator not found at $GEN"; exit 1; }

TMP="$(harness_tmpdir)"

assert_exit() {
  local name="$1" want="$2"; shift 2
  local out got
  out=$("$@" 2>&1); got=$?
  if [ "$got" -eq "$want" ]; then ok "$name"; else bad "$name" "expected exit $want, got $got: ${out:0:300}"; fi
}
# A small fixture with two domains and three skills, plus a gold fixture that
# sits deeper than the glob and must never be mirrored.
make_fixture() {
  local d="$1"
  mkdir -p "$d/skills/toolkit/alpha" "$d/skills/repo/beta" "$d/skills/repo/gamma" "$d/skills/repo/_contract/fixtures/demo/skills/deep"
  for s in toolkit/alpha repo/beta repo/gamma; do
    printf -- '---\nname: %s\ndescription: d\n---\n' "$(basename "$s")" > "$d/skills/$s/SKILL.md"
  done
  printf -- '---\nname: deep\ndescription: d\n---\n' > "$d/skills/repo/_contract/fixtures/demo/skills/deep/SKILL.md"
  bash "$GEN" "$d" >/dev/null 2>&1
}

section "the committed mirror"
assert_exit "build-agents-skills.sh --check passes on the tree" 0 bash "$GEN" "$ROOT" --check
assert_exit "--help exits 0" 0 bash "$GEN" --help
assert_exit "an unknown flag is rejected" 1 bash "$GEN" "$ROOT" --bogus
judge ".agents/skills exists" yes "$(exists "$MIRROR")"

canon="$(find "$ROOT/skills" -mindepth 3 -maxdepth 3 -name SKILL.md | wc -l | tr -d ' ')"
mirrored="$(find "$MIRROR" -mindepth 1 -maxdepth 1 | wc -l | tr -d ' ')"
judge "one entry per canonical skill ($canon)" "$canon" "$mirrored"
judge "the mirror is not empty" yes "$(if [ "$mirrored" -gt 0 ]; then echo yes; else echo no; fi)"

notlink=""; dangling=""; absolute=""; wrongtarget=""
for e in "$MIRROR"/*; do
  n="$(basename "$e")"
  [ -L "$e" ] || { notlink="$notlink $n"; continue; }
  t="$(readlink "$e")"
  case "$t" in /*) absolute="$absolute $n" ;; esac
  [ -f "$e/SKILL.md" ] || dangling="$dangling $n"
  case "$t" in ../../skills/*/"$n") ;; *) wrongtarget="$wrongtarget $n->$t" ;; esac
done
judge "every entry is a symlink" "" "$notlink"
judge "every link is relative" "" "$absolute"
judge "every link resolves to a SKILL.md" "" "$dangling"
judge "every link points at skills/<domain>/<name> for its own name" "" "$wrongtarget"
judge "the reverse holds: every canonical skill is mirrored" "" \
  "$(find "$ROOT/skills" -mindepth 3 -maxdepth 3 -name SKILL.md | while read -r f; do n="$(basename "$(dirname "$f")")"; [ -L "$MIRROR/$n" ] || printf ' %s' "$n"; done)"
judge "a one-level scan finds every SKILL.md through the links" "$canon" \
  "$(find -L "$MIRROR" -mindepth 2 -maxdepth 2 -name SKILL.md | wc -l | tr -d ' ')"
gold=""; for g in demo example-skill deep; do [ -e "$MIRROR/$g" ] && gold="$gold $g"; done
judge "no gold fixture is mirrored" "" "$gold"
if [ -d "$ROOT/.gemini/skills" ]; then
  judge "membership agrees with .gemini/skills/" "" \
    "$(diff <(ls "$MIRROR" | sort) <(ls "$ROOT/.gemini/skills" | sort) || true)"
else
  skip "agreement with .gemini/skills" ".gemini/skills not present"
fi

section "planted drift fails --check (scratch fixtures)"
F="$TMP/healthy"; make_fixture "$F"
assert_exit "a healthy fixture passes --check" 0 bash "$GEN" "$F" --check
judge "the fixture mirrors exactly its three skills" "alpha beta gamma" "$(ls "$F/.agents/skills" | sort | tr '\n' ' ' | sed 's/ $//')"
judge "the deeper gold fixture is not mirrored" no "$(exists "$F/.agents/skills/deep")"

F="$TMP/extra"; make_fixture "$F"; ln -s ../../skills/repo/beta "$F/.agents/skills/ghost"
assert_exit "a stale extra entry fails --check" 1 bash "$GEN" "$F" --check
assert_exit "a normal run prunes it" 0 bash "$GEN" "$F"
judge "the stale entry is gone" no "$(exists "$F/.agents/skills/ghost")"

F="$TMP/missing"; make_fixture "$F"; rm "$F/.agents/skills/beta"
assert_exit "a missing entry fails --check" 1 bash "$GEN" "$F" --check

F="$TMP/newskill"; make_fixture "$F"
mkdir -p "$F/skills/toolkit/delta"; printf -- '---\nname: delta\ndescription: d\n---\n' > "$F/skills/toolkit/delta/SKILL.md"
assert_exit "a new canonical skill without a regenerate fails --check" 1 bash "$GEN" "$F" --check
assert_exit "...and passes after a regenerate" 0 bash "$GEN" "$F"
judge "the new skill is linked" yes "$(exists "$F/.agents/skills/delta/SKILL.md")"

F="$TMP/dangling"; make_fixture "$F"; rm -rf "$F/skills/repo/gamma"
assert_exit "a deleted canonical skill (dangling link) fails --check" 1 bash "$GEN" "$F" --check

F="$TMP/absolute"; make_fixture "$F"; rm "$F/.agents/skills/alpha"; ln -s "$F/skills/toolkit/alpha" "$F/.agents/skills/alpha"
assert_exit "an absolute link in place of the relative one fails --check" 1 bash "$GEN" "$F" --check

F="$TMP/nomirror"; make_fixture "$F"; rm -rf "$F/.agents"
assert_exit "a missing mirror fails --check" 1 bash "$GEN" "$F" --check

F="$TMP/collide"; make_fixture "$F"
mkdir -p "$F/skills/toolkit/beta"; printf -- '---\nname: beta\ndescription: d\n---\n' > "$F/skills/toolkit/beta/SKILL.md"
assert_exit "a cross-domain name collision is exit 2" 2 bash "$GEN" "$F"

F="$TMP/empty"; mkdir -p "$F/skills"
assert_exit "an empty skills/ tree is exit 2 (never an empty mirror)" 2 bash "$GEN" "$F"

section "housekeeping"
judge "this test file is executable" yes "$(if [ -x "$ROOT/tests/test-agents-skills.sh" ]; then echo yes; else echo no; fi)"
judge "the generator is executable" yes "$(if [ -x "$GEN" ]; then echo yes; else echo no; fi)"

harness_summary
